Fixes: 8610c7c6e3bd ("net: ipv6: add support for rpl sr exthdr")
Cc: stable <stable@kernel.org>
Reported-by: Anthropic
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Link: https://patch.msgid.link/2026042133-gout-unvented-1bd9@gregkh
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug occurs because in `ipv6_rpl_srh_rcv()` (net/ipv6/exthdrs.c), headroom expansion via `pskb_expand_head()` is only done when `segments_left == 0`, but the recompressed SRH can grow larger than the original header (by up to 8 bytes) on any segment swap. This leads to insufficient headroom when `skb_push()` is called, followed by `skb_mac_header_rebuild()` writing `mac_len` bytes past the buffer, causing a buffer overflow. Additionally, the expansion size did not account for the MAC header space needed by `skb_mac_header_rebuild()`.

Here is the patch:

 static int ipv6_rpl_srh_rcv(struct sk_buff *skb)
 {
 	struct ipv6_rpl_sr_hdr *hdr, *ohdr, *chdr;
 	struct inet6_skb_parm *opt = IP6CB(skb);
 	struct net *net = dev_net(skb->dev);
 	struct inet6_dev *idev;
 	struct ipv6hdr *oldhdr;
+	unsigned int chdr_len;
 	unsigned char *buf;
 	int accept_rpl_seg;
 	int i, err;
 	u64 n = 0;
 	u32 r;

 	idev = __in6_dev_get(skb->dev);

 	accept_rpl_seg = min(READ_ONCE(net->ipv6.devconf_all->rpl_seg_enabled),
 			     READ_ONCE(idev->cnf.rpl_seg_enabled));
 	if (!accept_rpl_seg) {
 		kfree_skb(skb);
 		return -1;
 	}

 looped_back:
 	hdr = (struct ipv6_rpl_sr_hdr *)skb_transport_header(skb);

 	if (hdr->segments_left == 0) {
 		if (hdr->nexthdr == NEXTHDR_IPV6) {
 			int offset = (hdr->hdrlen + 1) << 3;

 			skb_postpull_rcsum(skb, skb_network_header(skb),
 					   skb_network_header_len(skb));
 			skb_pull(skb, offset);
 			skb_postpull_rcsum(skb, skb_transport_header(skb),
 					   offset);

 			skb_reset_network_header(skb);
 			skb_reset_transport_header(skb);
 			skb->encapsulation = 0;

 			__skb_tunnel_rx(skb, skb->dev, net);

 			netif_rx(skb);
 			return -1;
 		}

 		opt->srcrt = skb_network_header_len(skb);
 		opt->lastopt = opt->srcrt;
 		skb->transport_header += (hdr->hdrlen + 1) << 3;
 		opt->nhoff = (&hdr->nexthdr) - skb_network_header(skb);

 		return 1;
 	}

 	n = (hdr->hdrlen << 3) - hdr->pad - (16 - hdr->cmpre);
 	r = do_div(n, (16 - hdr->cmpri));
 	/* checks if calculation was without remainder and n fits into
 	 * unsigned char which is segments_left field. Should not be
 	 * higher than that.
 	 */
 	if (r || (n + 1) > 255) {
 		kfree_skb(skb);
 		return -1;
 	}

 	if (hdr->segments_left > n + 1) {
 		__IP6_INC_STATS(net, idev, IPSTATS_MIB_INHDRERRORS);
 		icmpv6_param_prob(skb, ICMPV6_HDR_FIELD,
 				  ((&hdr->segments_left) -
 				   skb_network_header(skb)));
 		return -1;
 	}

 	hdr->segments_left--;
 	i = n - hdr->segments_left;

 	buf = kcalloc(struct_size(hdr, segments.addr, n + 2), 2, GFP_ATOMIC);
 	if (unlikely(!buf)) {
 		kfree_skb(skb);
 		return -1;
 	}

 	ohdr = (struct ipv6_rpl_sr_hdr *)buf;
 	ipv6_rpl_srh_decompress(ohdr, hdr, &ipv6_hdr(skb)->daddr, n);
 	chdr = (struct ipv6_rpl_sr_hdr *)(buf + ((ohdr->hdrlen + 1) << 3));

 	if (ipv6_addr_is_multicast(&ohdr->rpl_segaddr[i])) {
 		kfree_skb(skb);
 		kfree(buf);
 		return -1;
 	}

 	err = ipv6_chk_rpl_srh_loop(net, ohdr->rpl_segaddr, n + 1);
 	if (err) {
 		icmpv6_send(skb, ICMPV6_PARAMPROB, 0, 0);
 		kfree_skb(skb);
 		kfree(buf);
 		return -1;
 	}

 	swap(ipv6_hdr(skb)->daddr, ohdr->rpl_segaddr[i]);

 	ipv6_rpl_srh_compress(chdr, ohdr, &ipv6_hdr(skb)->daddr, n);

 	oldhdr = ipv6_hdr(skb);

 	skb_pull(skb, ((hdr->hdrlen + 1) << 3));
 	skb_postpull_rcsum(skb, oldhdr,
 			   sizeof(struct ipv6hdr) + ((hdr->hdrlen + 1) << 3));
-	if (unlikely(!hdr->segments_left)) {
-		if (pskb_expand_head(skb, sizeof(struct ipv6hdr) + ((chdr->hdrlen + 1) << 3), 0,
+	chdr_len = sizeof(struct ipv6hdr) + ((chdr->hdrlen + 1) << 3);
+	if (unlikely(!hdr->segments_left ||
+		     skb_headroom(skb) < chdr_len + skb->mac_len)) {
+		if (pskb_expand_head(skb, chdr_len + skb->mac_len, 0,
 				     GFP_ATOMIC)) {
 			__IP6_INC_STATS(net, ip6_dst_idev(skb_dst(skb)), IPSTATS_MIB_OUTDISCARDS);
 			kfree_skb(skb);
 			kfree(buf);
 			return -1;
 		}

 		oldhdr = ipv6_hdr(skb);
 	}
-	skb_push(skb, ((chdr->hdrlen + 1) << 3) + sizeof(struct ipv6hdr));
+	skb_push(skb, chdr_len);
 	skb_reset_network_header(skb);
 	skb_mac_header_rebuild(skb);
 	skb_set_transport_header(skb, sizeof(struct ipv6hdr));

 	memmove(ipv6_hdr(skb), oldhdr, sizeof(struct ipv6hdr));
 	memcpy(skb_transport_header(skb), chdr, (chdr->hdrlen + 1) << 3);

 	ipv6_hdr(skb)->payload_len = htons(skb->len - sizeof(struct ipv6hdr));
 	skb_postpush_rcsum(skb, ipv6_hdr(skb),
 			   sizeof(struct ipv6hdr) + ((chdr->hdrlen + 1) << 3));

 	kfree(buf);

 	ip6_route_input(skb);

 	if (skb_dst(skb)->error) {
 		dst_input(skb);
 		return -1;
 	}

 	if (skb_dst_dev(skb)->flags & IFF_LOOPBACK) {
 		if (ipv6_hdr(skb)->hop_limit <= 1) {
 			__IP6_INC_STATS(net, idev, IPSTATS_MIB_INHDRERRORS);
 			icmpv6_send(skb, ICMPV6_TIME_EXCEED,
 				    ICMPV6_EXC_HOPLIMIT, 0);
 			kfree_skb(skb);
 			return -1;
 		}
 		ipv6_hdr(skb)->hop_limit--;

 		skb_pull(skb, sizeof(struct ipv6hdr));
 		goto looped_back;
 	}

 	dst_input(skb);

 	return -1;
 }



